"""Command line: prepare-data, train, predict, report."""
from __future__ import annotations

import argparse
import json
from pathlib import Path

import joblib
import numpy as np
import pandas as pd

from .data import prepare_data
from .features import make_features
from .targets import CLASSES


def load_config(path: str | Path) -> dict:
    return json.loads(Path(path).read_text())


def predict_csv(model_path: Path, csv_path: Path, output: Path, all_rows: bool = False) -> pd.DataFrame:
    # Only load trusted joblib artifacts generated by this project.
    bundle = joblib.load(model_path)
    if bundle.get("schema_version") != 1:
        raise ValueError("Unsupported model artifact version")
    frame = pd.read_csv(csv_path)
    if "timestamp" not in frame.columns:
        raise ValueError("Input CSV requires a timestamp column")
    frame.index = pd.to_datetime(frame.pop("timestamp"), utc=True)
    required = set(bundle["required_columns"])
    if not required.issubset(frame.columns):
        raise ValueError(f"Missing input columns: {sorted(required - set(frame.columns))}")
    if "minute_count" in frame.columns and not frame["minute_count"].eq(240).all():
        raise ValueError("Input includes incomplete 4H candles")
    x = make_features(frame, bundle["lookback"])
    eligible = x.notna().any(axis=1)
    if not eligible.any():
        raise ValueError(f"Need at least {bundle['lookback']} consecutive complete 4H candles")
    if not all_rows:
        if not eligible.iloc[-1]:
            raise ValueError("Latest candle lacks a complete lookback; refusing a stale prediction")
        eligible = eligible & (x.index == x.index[-1])
    p = bundle["model"].predict_proba(x.loc[eligible, bundle["feature_columns"]])
    result = pd.DataFrame({"timestamp": x.index[eligible], "decision_time": x.index[eligible] + pd.Timedelta(hours=4),
                           "target_end_time": x.index[eligible] + pd.Timedelta(hours=28),
                           "predicted_regime": np.asarray(CLASSES)[p.argmax(axis=1)],
                           "confidence": p.max(axis=1)})
    for i, name in enumerate(CLASSES):
        result[f"prob_{name}"] = p[:, i]
    output.parent.mkdir(parents=True, exist_ok=True)
    result.to_csv(output, index=False)
    return result


def main(argv=None) -> None:
    parser = argparse.ArgumentParser(description="4H crypto regime classification with honest time-series evaluation")
    sub = parser.add_subparsers(dest="command", required=True)
    common = argparse.ArgumentParser(add_help=False)
    common.add_argument("--config", type=Path, default=Path("configs/experiment.json"))
    common.add_argument("--data-dir", type=Path, default=Path("data"))
    common.add_argument("--sources", type=Path, default=Path("configs/sources.json"))
    common.add_argument("--archive-dir", type=Path, default=Path(".cache/archives"))
    p = sub.add_parser("prepare-data", parents=[common], help="Download pinned archives and aggregate complete 4H candles")
    p = sub.add_parser("train", parents=[common], help="Run validation search and final test, publish all results")
    p.add_argument("--output", type=Path, default=Path("results"))
    p.add_argument("--threads", type=int, default=2)
    p.add_argument("--stage", choices=["all", "validate"], default="all")
    p = sub.add_parser("predict", help="Predict next-24H regime from a trusted saved model and 4H CSV")
    p.add_argument("--model", type=Path, default=Path("results/models/regime_model.joblib"))
    p.add_argument("--csv", type=Path, required=True)
    p.add_argument("--output", type=Path, default=Path("predictions.csv"))
    p.add_argument("--all-rows", action="store_true")
    p = sub.add_parser("report", help="Regenerate report/figures from existing test artifacts without retraining")
    p.add_argument("--config", type=Path, default=Path("configs/experiment.json"))
    p.add_argument("--data-dir", type=Path, default=Path("data"))
    p.add_argument("--output", type=Path, default=Path("results"))
    args = parser.parse_args(argv)
    if args.command in {"prepare-data", "train"}:
        config = load_config(args.config)
        manifest_path = args.data_dir / "manifest.json"
        needed = not manifest_path.exists() or not all((args.data_dir / f"{s}_4h.parquet").exists() for s in config["symbols"])
        if needed or args.command == "prepare-data":
            prepare_data(args.data_dir, args.archive_dir, args.sources, config["symbols"], config["data_start"], config["data_end_exclusive"])
        if args.command == "train":
            from .experiment import run_experiment
            run_experiment(args.data_dir, args.config, args.output, args.threads, args.stage)
    elif args.command == "predict":
        result = predict_csv(args.model, args.csv, args.output, args.all_rows)
        print(result.to_string(index=False))
    elif args.command == "report":
        from .report import create_report
        create_report(args.output, args.data_dir, load_config(args.config))
        print(f"Report regenerated: {args.output / 'test_results.md'}")
